        cnt++;
        cur = cur->next;
    } while (cur != head);
    printf("(head: %d) [total: %d]\n", head->data, cnt);
}

void free_list(Node** head) {
    if (!*head) return;
    Node* cur = *head;
    Node* last = *head;
